import { useRef, useState } from "react";

export function NoteEditor({ note, saveNote, onSaved }) {
  const [text, setText] = useState(note.text);
  const [status, setStatus] = useState("idle");   // idle | pending | error | conflict.
  const [message, setMessage] = useState("");
  const pending = useRef(false);                   // sync guard, not a snapshot.

  async function handleSave(e) {
    e.preventDefault();
    if (pending.current) return;
    pending.current = true;
    setStatus("pending");
    const res = await saveNote({ id: note.id, text, version: note.version });
    pending.current = false;
    if (res.ok) {
      onSaved(res.note);                           // server's version, trimmed text, new time.
      setText(res.note.text);
      setStatus("idle");
    } else if (res.status === 409) {
      setStatus("conflict");
      setMessage("This note changed elsewhere. Reload to see the latest.");
    } else {
      setStatus("error");
      setMessage(res.message ?? "Couldn't save. Your text is still here.");
    }
  }

  return (
    <form onSubmit={handleSave}>
      <label>Note <textarea value={text} onChange={(e) => setText(e.target.value)} /></label>
      <button type="submit" disabled={status === "pending"}>{status === "pending" ? "Saving..." : "Save"}</button>
      {message && <p role="alert">{message}</p>}
    </form>
  );
}
